contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address _recipient) public payable {
        uint256 cBalBefore = address(c).balance;
        uint256 recipientBalBefore = _recipient.balance;

        bool reverted;
        c.withdrawAll(_recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            (reverted && address(c).balance == cBalBefore)
            ||
            (!reverted && address(c).balance == 0 && _recipient.balance == recipientBalBefore + cBalBefore)
        );
    }
}

